  for (std::size_t offset = 0; offset < expected.size(); ++offset) 
  { 
    cex::Copy(input, data_start + offset * num_features, num_features, cuda_env_->Stream());
    model.PreProcess();
    model.Infer(input.get());
    model.Output(output.get());
